 1	/**
 2	 * Tests for the week data loader against the real public/ folder.
 3	 * The week 6 JSON is the fixture, so these tests break if the publish layout changes.
 4	 */
 5	import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
 6	import { tmpdir } from "node:os";
 7	import { join } from "node:path";
 8	import { afterEach, describe, expect, it, vi } from "vitest";
 9	import { weekPageJson } from "@/fixtures/week-page-json";
10	import { listWeeks, listWeekSummaries, loadWeek } from "./week-data";
11	
12	describe("listWeeks", () => {
13	  it("lists week 6 of 2026 by its folder names", () => {
14	    expect(listWeeks()).toContainEqual({ season: "2026", week: "week-06" });
15	  });
16	});
17	
18	describe("loadWeek", () => {
19	  it("reads the week 6 page JSON", () => {
20	    const page = loadWeek("2026", "week-06");
21	    expect(page.week).toBe(6);
22	    expect(page.season).toBe(2026);
23	    expect(page.pick.sides[0].team.name).toBe("behold the lamb");
24	    expect(page.avatars["10"]).toBe("avatars/10.jpg");
25	  });
26	});
27	
28	describe("loadWeek schema check", () => {
29	  afterEach(() => {
30	    vi.restoreAllMocks();
31	  });
32	
33	  it("throws when the schema version is not 2", async () => {
34	    // A temp public/ folder holds a page at the old version.
35	    const root = mkdtempSync(join(tmpdir(), "week-data-"));
36	    mkdirSync(join(root, "public", "2026", "week-01"), { recursive: true });
37	    writeFileSync(join(root, "public", "2026", "week-01", "page.json"), JSON.stringify({ schema_version: 1 }));
38	    vi.spyOn(process, "cwd").mockReturnValue(root);
39	    // The module reads the working folder when it loads, so reset it to pick up the temp folder.
40	    vi.resetModules();
41	    const { loadWeek: load } = await import("./week-data");
42	    expect(() => load("2026", "week-01")).toThrow(/schema_version 1/);
43	  });
44	});
45	
46	describe("listWeekSummaries", () => {
47	  it("summarizes week 6 with its dates, its link, and the teams of its Matchup of the Week", () => {
48	    expect(listWeekSummaries()).toContainEqual({
49	      number: 6,
50	      dates: "Oct 15 – Oct 19, 2026",
51	      href: "/2026/week-06/",
52	      pickTeams: ["behold the lamb", "Bo Girds"],
53	    });
54	  });
55	
56	  it("sorts the newest week first", () => {
57	    const numbers = listWeekSummaries().map((summary) => summary.number);
58	    expect(numbers).toEqual([...numbers].sort((a, b) => b - a));
59	  });
60	
61	  it("sorts by season, then by week, as numbers", async () => {
62	    // A temp public/ folder holds weeks 2 and 10 of 2026 and week 1 of 2027.
63	    const root = mkdtempSync(join(tmpdir(), "week-data-"));
64	    for (const [season, week, number] of [
65	      ["2026", "week-02", 2],
66	      ["2026", "week-10", 10],
67	      ["2027", "week-01", 1],
68	    ] as const) {
69	      mkdirSync(join(root, "public", season, week), { recursive: true });
70	      writeFileSync(
71	        join(root, "public", season, week, "page.json"),
72	        weekPageJson({ week: number, dates: "d" }),
73	      );
74	    }
75	    vi.spyOn(process, "cwd").mockReturnValue(root);
76	    vi.resetModules();
77	    const { listWeekSummaries: list } = await import("./week-data");
78	    expect(list().map((summary) => summary.href)).toEqual(["/2027/week-01/", "/2026/week-10/", "/2026/week-02/"]);
79	  });
80	});
